import os
import re

def check_detailed(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    lines = content.splitlines()
    sections = {}
    current_section = None

    for line in lines:
        stripped = line.strip()
        if stripped.startswith('[') and stripped.endswith(']'):
            current_section = stripped[1:-1].lower()
        elif current_section == 'veritabani':
            if re.match(r'^port\s*=\s*5432', stripped, re.IGNORECASE):
                return f"HATA: 5432 hala var: {line}"
            if re.match(r'^port\s*=\s*6543', stripped, re.IGNORECASE):
                return "OK: 6543 olarak güncellenmiş"
            if re.match(r'^port\s*=', stripped, re.IGNORECASE):
                return f"DIŞARDA: Port farklı değerde: {line}"

    # Eğer veritabanı bölümündeyse ve port hiç yoksa veya farklıysa
    # (Bu kısım sadece kontrol amaçlı)
    return "OK: Port 6543 veya bölümde port yok"

files = ['.\\servisler\\api.ini', '.\\servisler\\rapor.ini', '.\\servisler\\web.ini', '.\\servisler\\odeme\\odeme.ini']
for f in files:
    print(f"{f}: {check_detailed(f)}")

